I did not add the metadata fetch. The node's `with` clause grants only `aap:caps/state-read@0.1.0`, and calling `https://metadata.internal.example/enrich` would need `aap:caps/http-client`, which would exceed that authority. The output is unchanged either way.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{run-info, subscription-list};

    import aap:caps/state-read@0.1.0;

    export run: func(info: run-info) -> subscription-list;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let urls = match state_read::get("subscriptions") {
            Some(raw) => raw
                .lines()
                .map(|l| l.trim())
                .filter(|l| !l.is_empty())
                .map(|l| l.to_string())
                .collect(),
            None => Vec::new(),
        };
        SubscriptionList { urls }
    }
}

export!(Node);
```

